<script lang="ts">
  import { indexGuideline, loadGuideline, markReady, readHash, writeHash, type Guideline, type HashState, type Concept } from '../../shared/data.js';
  let g = $state.raw<Guideline | null>(null);
  let state = $state.raw<HashState>(readHash());
  let mode = $state('concepts');
  let order = $state('guideline');
  let search = $state('');
  let chosen = $state.raw<{rec:number; concept?:Concept; other?:number}|null>(null);
  const ix = $derived(g ? indexGuideline(g) : null);
  const family = (key:string) => ix?.docs.get(key.slice(0,key.lastIndexOf(':')))?.rec;
  const eligible = (c:Concept) => c.kind === 'entity' && !/^(patient|clinician|person|therapy|treatment|opioid-pain-clinical-practice-guideline)$/i.test(c.label);
  const concepts = $derived(g?.concepts.filter(eligible) ?? []);
  const mentionIndex = $derived.by(()=>{ const index=new Map<string,Map<number,string[]>>(); for(const c of concepts){const groups=new Map<number,string[]>();for(const key of c.mentions){const rec=family(key);if(rec!=null){const keys=groups.get(rec)??[];keys.push(key);groups.set(rec,keys);}}index.set(c.id,groups);}return index; });
  const members = (c:Concept, rec:number) => mentionIndex.get(c.id)?.get(rec) ?? [];
  const sharedIndex = $derived.by(()=>{const index=new Map<string,Concept[]>();for(const a of g?.recommendations??[])for(const b of g?.recommendations??[])index.set(`${a.number}:${b.number}`,concepts.filter(c=>members(c,a.number).length&&members(c,b.number).length));return index;});
  const shared = (a:number,b:number) => sharedIndex.get(`${a}:${b}`) ?? [];
  const columns = $derived([...concepts].sort((a,b)=>b.mentions.length-a.mentions.length || a.label.localeCompare(b.label)).slice(0,12));
  const recs = $derived([...(g?.recommendations ?? [])].sort((a,b)=> order==='density' ? columns.reduce((s,c)=>s+members(c,b.number).length-members(c,a.number).length,0) : a.number-b.number));
  const max = $derived(Math.max(1,...recs.flatMap(r => columns.map(c => members(c,r.number).length))));
  const selectedKeys = $derived(chosen?.concept ? members(chosen.concept,chosen.rec) : chosen?.other ? [...new Set(shared(chosen.rec,chosen.other).flatMap(c=>[...members(c,chosen.rec),...members(c,chosen.other!)]))] : []);
  const question = $derived(state.view==='trace' ? g?.questions.find(q=>q.id===state.question) : null);
  const ruleKey = $derived(state.view==='rule' ? `${state.document}:${state.sentence}` : '');
  const sentence = $derived(ix?.sentence(ruleKey));
  const rule = $derived(ix?.rules.get(ruleKey));
  const results = $derived(state.view==='explore' ? concepts.filter(c=>c.label.toLowerCase().includes(state.query.toLowerCase())) : []);
  function go(next:HashState) { state=next; chosen=null; writeHash(next); }
  function openKey(key:string) { const at=key.lastIndexOf(':'); go({view:'rule',document:key.slice(0,at),sentence:Number(key.slice(at+1))}); }
  function shade(n:number, ceiling:number) { return n===0 ? 'var(--surface-sunken)' : `color-mix(in srgb, #174f9e ${Math.round(72+28*Math.sqrt(n/ceiling))}%, #b4cde7)`; }
  $effect(()=>{ const listener=()=>{state=readHash();chosen=null}; addEventListener('hashchange',listener); void loadGuideline().then(data=>g=data); return()=>removeEventListener('hashchange',listener); });
  $effect(()=>{ if(g){void state; queueMicrotask(markReady);} });
</script>

<main>
  <header><span>CNL / CKC <span class="muted">Knowledge base atlas</span></span><span class="prototype">Graph prototype</span></header>
  <nav aria-label="Atlas views"><button class:active={state.view==='overview'} onclick={()=>go({view:'overview'})}>Guideline coverage</button><button class:active={state.view==='trace'} onclick={()=>go({view:'trace',question:g?.questions[0]?.id ?? ''})}>Trace an answer</button><button class:active={state.view==='explore'} onclick={()=>go({view:'explore',query:'naloxone'})}>Explore concepts</button></nav>
  {#if !g || !ix}<p>Loading the guideline…</p>{:else}
    <p class="muted">CDC Clinical Practice Guideline for Prescribing Opioids for Pain, 2022</p>
    <h1>{state.view==='overview' ? 'Where the guideline concentrates' : state.view==='trace' ? 'An answer, back to its source' : state.view==='rule' ? 'Inside one rule' : 'Find a clinical concept'}</h1>
    <p class="intro">{state.view==='overview' ? 'Rows are recommendation families. Columns are concepts. A filled cell links them by a sentence mention, not by a clinical implication.' : state.view==='trace' ? 'Follow each statement to its controlled-language sentence, document passage and guideline page.' : state.view==='rule' ? 'Read the condition and action together, then inspect the guideline passage that the rule encodes.' : 'Search the exported concepts and inspect where the guideline mentions them.'}</p>
    {#if state.view==='overview'}
      <div class="toolbar"><div><button class:active={mode==='concepts'} onclick={()=>{mode='concepts';chosen=null}}>Concept mentions</button><button class:active={mode==='shared'} onclick={()=>{mode='shared';chosen=null}}>Shared concepts</button></div><label>Row order <select bind:value={order}><option value="guideline">Guideline order</option><option value="density">Most mentions first</option></select></label></div>
      <div class="workspace"><section class="matrixpanel"><h2>{mode==='concepts' ? 'Clinical concept coverage' : 'Recommendation overlap'}</h2><p class="muted">{mode==='concepts' ? 'Top 12 concepts by sentence mentions. Counts include each family’s supporting documents.' : 'Number of distinct concepts shared by each pair. Diagonal = all concepts in that family.'}</p><div class="matrixscroll" role="region" aria-label="Scrollable count table"><table><thead><tr><th class="rowhead">Recommendation</th>{#each (mode==='concepts' ? columns : g.recommendations) as c}<th class="column"><span>{'label' in c ? c.label : `Rec ${c.number}`}</span></th>{/each}</tr></thead><tbody>{#each recs as r}<tr><th class="rowhead"><button onclick={()=>go({view:'rule',document:r.id,sentence:ix!.docs.get(r.id)!.sentences[0].n})}>Rec {r.number}</button></th>{#each (mode==='concepts' ? columns : g.recommendations) as c}{@const n='label' in c ? members(c,r.number).length : shared(r.number,c.number).length}<td><button class="cell" class:empty={n===0} style:background={shade(n,mode==='concepts'?max:concepts.length)} aria-label={`Recommendation ${r.number}, ${'label' in c ? c.label : `Recommendation ${c.number}`}: ${n}`} onclick={()=>chosen='label' in c ? {rec:r.number,concept:c} : {rec:r.number,other:c.number}}>{n || '·'}</button></td>{/each}</tr>{/each}</tbody></table></div><p class="legend"><span class="swatch"></span> More mentions = darker blue. Numbers are exact. Empty cells contain zero mentions in this projection.</p></section>
      <aside><h2>{chosen ? `Recommendation ${chosen.rec}` : 'Read a cell'}</h2>{#if chosen}<h3>{chosen.concept?.label ?? `Shared with recommendation ${chosen.other}`}</h3><p>{selectedKeys.length} source sentences</p>{#if chosen.other}<p class="muted">{shared(chosen.rec,chosen.other).map(c=>c.label).join(', ')}</p>{/if}{#each selectedKeys as key}<button class="evidence" onclick={()=>openKey(key)}><small>{key}</small><span>{ix.sentence(key)?.ace}</span></button>{/each}{#if !selectedKeys.length}<p>No mentions in this cell. This does not establish clinical absence.</p>{/if}{:else}<p>Select any intersection to inspect the sentences behind its count.</p><p class="muted">Compare rows for a topic’s reach. Compare columns for a recommendation’s vocabulary.</p><h3>{g.recommendations.length} recommendation families</h3><p>{g.documents.length} exported documents form the evidence beneath this view.</p>{/if}</aside></div>
    {:else if state.view==='trace'}
      <label class="question">Choose a question <select value={question?.id ?? ''} onchange={e=>go({view:'trace',question:e.currentTarget.value})}>{#each g.questions as q}<option value={q.id}>{q.question}</option>{/each}</select></label>
      <p class="notice">{g.derivation}</p>
      {#if !question}<p>Question not found.</p>{:else}<h2>{question.question}</h2><ol class="trace">{#each question.statements as s}{@const d=ix.docs.get(s.document)!}<li><p>{ix.sentence(`${s.document}:${s.sentence}`)?.ace}</p><div class="path"><button onclick={()=>go({view:'rule',document:s.document,sentence:s.sentence})}>Read rule and sentence {s.sentence}</button><span>from {s.document}</span><a href={`${g.pdf}#page=${d.page}`} target="_blank" rel="noreferrer">Guideline page {d.page}</a></div><details><summary>Read the source passage</summary><p>{d.source}</p></details></li>{/each}</ol><details><summary>Prolog goal used by the live demo</summary><pre>{question.goal}</pre></details>{/if}
    {:else if state.view==='rule'}
      {#if !sentence}<p>Sentence not found.</p>{:else}{@const d=ix.docs.get(state.document)!}<div class="rulegrid"><section><h2>{d.id}, sentence {state.sentence}</h2><p class="statement">{sentence.ace}</p>{#if rule}<div class="logic"><div><b>Condition</b><p>{rule.condition ?? 'No explicit condition in this rule.'}</p></div><div><b>{rule.subject} {rule.mode}</b>{#each rule.actions as action}<p>{action.polarity==='negative' ? 'not ' : ''}{action.verb} {action.object} {action.modifiers.map(m=>`${m.preposition} ${m.value}`).join(' ')}</p>{/each}</div></div>{:else}<h3>Text reading, not the KB’s clinical parse</h3><p>Condition: {sentence.condition ?? 'No condition identified by the text split.'}</p><p>Conclusion: {sentence.conclusion}</p>{/if}</section><aside><h2>Source passage</h2><a href={`${g.pdf}#page=${d.page}`} target="_blank" rel="noreferrer">Open guideline page {d.page}</a><p>{d.source}</p></aside></div><h3>Concepts mentioned in this sentence</h3><div class="conceptlist">{#each concepts.filter(c=>c.mentions.includes(ruleKey)) as c}<button onclick={()=>go({view:'explore',query:c.label})}>{c.label}</button>{/each}</div>{/if}
    {:else}
      <form onsubmit={e=>{e.preventDefault();go({view:'explore',query:search})}}><label>Concept name <input bind:value={search} placeholder={state.query}/></label><button>Find concepts</button></form><h2>{results.length} concepts matching “{state.query}”</h2>{#each results as c}<section class="result"><h3>{c.label}</h3><p>{c.mentions.length} sentence mentions</p><div class="bars">{#each g.recommendations.filter(r=>members(c,r.number).length) as r}{@const n=members(c,r.number).length}<button onclick={()=>{chosen={rec:r.number,concept:c};go({view:'rule',document:members(c,r.number)[0].split(':')[0],sentence:Number(members(c,r.number)[0].split(':')[1])})}}><span>Rec {r.number}</span><span class="bar" style:width={`${Math.max(2,80*n/c.mentions.length)}%`}></span><b>{n}</b></button>{/each}</div><details><summary>Read every mentioning sentence</summary>{#each c.mentions as key}<button class="evidence" onclick={()=>openKey(key)}><small>{key}</small><span>{ix.sentence(key)?.ace}</span></button>{/each}</details></section>{/each}{#if !results.length}<p>No matching concept. Try a shorter term.</p>{/if}
    {/if}
    <footer><details><summary>Scope exclusions ({g.exclusions.length} source records)</summary><p>These recommendations do not apply under the conditions below. Absence of an exclusion does not establish inclusion.</p>{#each g.exclusions as x}<p><button class="textlink" onclick={()=>go({view:'rule',document:x.document,sentence:x.sentence})}>{x.document}, sentence {x.sentence}</button><br/>{x.ace}</p>{/each}</details><details><summary>Superseded statements ({g.supersessions.length})</summary>{#each g.supersessions as x}<p><s>{x.ace}</s><br/>Superseded {String(x.date).slice(0,4)}-{String(x.date).slice(4,6)}-{String(x.date).slice(6)}: <a href={x.url}>{x.citation}</a><br/><button class="textlink" onclick={()=>go({view:'rule',document:x.document,sentence:x.sentence})}>Read {x.document}, sentence {x.sentence}</button></p>{/each}</details><p class="muted">Prototype projection from the exported KB. Not clinical advice. CDC material is free on the agency website. CDC does not endorse this demo.</p></footer>
  {/if}
</main>

<style>
  main{max-width:1480px;margin:auto;padding:24px 40px 40px}header{display:flex;justify-content:space-between;gap:12px;align-items:center;padding-bottom:20px}header>span:first-child{font-weight:700}header .muted{margin-left:20px;font-weight:400}.prototype{color:var(--text-muted);font-size:13px}nav{display:flex;gap:6px;border-bottom:1px solid var(--border);padding-bottom:12px;margin-bottom:28px}button,select,input{color:var(--text);background:var(--surface-raised);border:1px solid var(--border);border-radius:3px;padding:7px 12px;font:inherit}button,a,summary{cursor:pointer}button:hover{border-color:var(--action)}button.active{background:var(--action);color:var(--action-text);border-color:var(--action)}:is(button,select,input,a,summary):focus-visible{outline:3px solid var(--focus-ring);outline-offset:3px}a,.textlink{color:var(--action)}h1{font-size:34px;line-height:1.15;margin:8px 0 14px;letter-spacing:-.6px}h2{font-size:21px;line-height:1.3;margin:0 0 10px}h3{font-size:17px;line-height:1.4}p{max-width:76ch}.muted{color:var(--text-muted)}.intro{margin-bottom:28px;max-width:82ch}.toolbar{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:20px;flex-wrap:wrap}.toolbar>div{display:flex;gap:5px}.toolbar label{display:flex;align-items:center;gap:8px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:28px}.matrixpanel{min-width:0}.matrixpanel>p{font-size:13px}.matrixscroll{overflow:auto;max-width:100%;padding-bottom:10px}table{border-spacing:3px;width:100%;table-layout:fixed;font-size:12px}th{font-weight:500}.column{height:150px;vertical-align:bottom;padding-bottom:9px}.column span{writing-mode:vertical-rl;transform:rotate(180deg);white-space:normal;text-align:left;max-height:150px;line-height:1.15}.rowhead{width:88px;text-align:left;position:sticky;left:0;background:var(--surface);z-index:1}.rowhead button{border:0;background:transparent;padding:7px 2px;font-weight:600;font-size:13px}td{padding:0}.cell{border:0;width:100%;padding:8px 0;color:white;border-radius:0;min-width:25px;font-size:12px;font-weight:600}.cell.empty{color:var(--text-muted)}.cell:focus-visible{outline-offset:-2px}.legend{font-size:12px;display:flex;align-items:center;gap:9px}.swatch{width:38px;height:12px;background:#174f9e;flex-shrink:0}aside{background:var(--surface-raised);padding:20px;border-top:4px solid var(--action);min-width:0;max-height:710px;overflow:auto}aside p{font-size:14px}.evidence{display:block;width:100%;text-align:left;margin:10px 0;background:transparent;border:0;border-bottom:1px solid var(--border);border-radius:0;padding:10px 0}.evidence small{display:block;color:var(--text-muted);overflow-wrap:anywhere}.evidence span{display:block;margin-top:5px}.notice{background:var(--surface-sunken);border-left:4px solid var(--action);padding:12px 16px;font-size:14px;max-width:none}.question{display:block}.question select{display:block;width:min(100%,700px);margin:7px 0 20px;white-space:normal}.trace{padding-left:26px}.trace li{padding:4px 0 24px 14px;border-bottom:1px solid var(--border);margin-bottom:15px}.trace li>p{font-size:19px}.path{display:flex;gap:15px;align-items:center;flex-wrap:wrap;font-size:14px}.trace details{margin-top:12px}.rulegrid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:30px}.statement{font-size:22px}.logic{display:grid;gap:0;max-width:650px}.logic>div{padding:20px;border-left:4px solid var(--action);background:var(--surface-sunken);margin-top:10px}.logic p{margin-bottom:0}.conceptlist{display:flex;gap:8px;flex-wrap:wrap}form{display:flex;gap:8px;align-items:end;flex-wrap:wrap;margin-bottom:28px}form label{display:grid;gap:5px}form input{max-width:100%;width:300px}.result{padding:20px 0;border-top:1px solid var(--border);max-width:850px}.result h3{margin:0}.bars{margin:20px 0}.bars button{display:flex;align-items:center;gap:15px;width:100%;border:0;background:transparent;text-align:left;padding-left:0}.bars button>span:first-child{min-width:50px}.bar{height:19px;background:var(--action);display:inline-block}.bars b{font-weight:500}footer{margin-top:35px;padding-top:18px;border-top:1px solid var(--border);font-size:13px}footer details{padding:9px 0}footer summary{font-size:15px}footer p{max-width:95ch}.textlink{border:0;background:transparent;padding:0;text-align:left}pre{white-space:pre-wrap;overflow-wrap:anywhere}summary{color:var(--action)}
  @media(min-width:751px){header{padding-bottom:12px}nav{margin-bottom:18px}.intro{margin-bottom:18px}.toolbar{margin-bottom:14px}.column{height:130px}.column span{max-height:130px}.cell{padding:5px 0}.rowhead button{padding:5px 2px}}
  @media(max-width:750px){main{padding:18px 18px 30px}header{align-items:start}header .muted{display:block;margin:4px 0 0}.prototype{max-width:80px;text-align:right}nav{gap:5px;flex-wrap:wrap;margin-bottom:20px}nav button{font-size:13px;padding:6px 8px}h1{font-size:29px}.intro{font-size:14px}.workspace,.rulegrid{grid-template-columns:1fr;gap:20px}.toolbar>div{width:100%}.toolbar button{font-size:13px}.toolbar label{font-size:13px}.matrixscroll table{min-width:590px}.column{height:125px}.column span{max-height:120px}.cell{padding:7px 0}aside{max-height:500px}.path{align-items:start;gap:9px}.path span{overflow-wrap:anywhere}.trace{padding-left:20px}.trace li{padding-left:5px}.trace li>p,.statement{font-size:18px}h2{overflow-wrap:anywhere}.legend{align-items:start}form input{width:260px}.rulegrid aside{max-height:none}}
  @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
